def carry_over_existing_records(apps, schema_editor):
    """Group existing lab tests into requests and turn each existing prescription into a one-line prescription."""
    LabOrder = apps.get_model('hospital', 'LabOrder')
    LabRequest = apps.get_model('hospital', 'LabRequest')
    Prescription = apps.get_model('hospital', 'Prescription')
    PrescriptionItem = apps.get_model('hospital', 'PrescriptionItem')
    Dispense = apps.get_model('hospital', 'Dispense')
    current, last_enc, last_time = None, None, None
    for o in LabOrder.objects.filter(request__isnull=True).order_by('encounter_id', 'created_at', 'id'):
        # tests ordered for the same visit within five minutes of each other were one request
        if current is None or o.encounter_id != last_enc or (o.created_at - last_time).total_seconds() > 300:
            current = LabRequest.objects.create(encounter_id=o.encounter_id, specimen_id=o.specimen_id)
            LabRequest.objects.filter(pk=current.pk).update(created_at=o.created_at)
        LabOrder.objects.filter(pk=o.pk).update(request=current)
        last_enc, last_time = o.encounter_id, o.created_at
    for p in Prescription.objects.filter(medication__isnull=False):
        item = PrescriptionItem.objects.create(prescription=p, medication_id=p.medication_id, quantity=p.quantity or 1,
                                               frequency='ASDIR', instructions=(p.directions or '')[:300])
        Dispense.objects.filter(prescription=p, item__isnull=True).update(item=item)


Migration.operations.append(migrations.RunPython(carry_over_existing_records, migrations.RunPython.noop))
